{
  "model": "Qwen3-TTS-12Hz-1.7B-Base",
  "input": {
    "text": "我现在做电商运营，最消耗我的是反复追指标、接临时需求和跨部门催进度。反而是访谈用户、归纳问题、做新人培训材料，还有把复杂项目讲清楚时，我会更投入。",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "qwen3-profile-741bad11d4fd5d88",
      "seed": 3450097999,
